-- Queer Atlas: verified UK and Ireland queer events, techno and culture batch.
-- Newcastle and nation-wide festivals are placed in global_events until city pages exist.

begin;

alter table if exists public.events add column if not exists event_intel jsonb not null default '{}'::jsonb;
alter table if exists public.events add column if not exists ticket_url text;
alter table if exists public.global_events add column if not exists ticket_url text;
alter table if exists public.global_events add column if not exists event_intel jsonb not null default '{}'::jsonb;

with src as (
 select * from jsonb_to_recordset($qa_uk_city_events$
[
{"name":"Satiate – October 2026","aliases":["Satiate October 2026","Satiate at radial October 2026"],"city":"london","date":"2026-10-11","start_date":"2026-10-11","end_date":"2026-10-11","description":"Satiate makes a Sunday in Tottenham feel like a mutual-aid rave: a music-first queer day party where techno, house and collective pleasure are explicitly tied to cheap entry and a direct contribution to gender-affirming care.","link":"https://ra.co/events/2536580","ticket_url":"https://ra.co/events/2536580","location":"radial, 39b Markfield Road, London N15 4QA, United Kingdom","lat":51.58715,"lng":-0.07072,"vibe":"queer techno and house day party with a mutual-aid backbone","intel":{"hours":"13:00–23:00 Sunday 11 October 2026.","entry_wait":"Tickets are £7–22; the low-price model is intentional, but capacity still applies, so buy before travelling.","best_arrival":"Arrive near 13:00 for the daytime social rhythm and the whole selector arc rather than only the late peak.","crowd_mix":"Queer dancers, allies and people who care about gender-affirming healthcare are the intended community, not a generic Sunday crowd.","dress_code":"No formal code is published; comfortable expressive day-rave clothing is the right read.","host_inclusivity":"All profits from this edition are pledged to Angel McQueen's gender-affirming surgery; access and redistribution are named founding principles.","lineup":"Jordan Hearns, J. Aria b2b Someone Sunny, FAFF, Riva b2b Teecra.","age_limit":"18+.","source_urls":["https://ra.co/events/2536580"],"research_status":"ticketing_listing_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"GLIMMER 001: Queer Techno Party","aliases":["GLIMMER 001 Dublin","Glimmer Queer Techno Dublin 2026"],"city":"dublin","date":"2026-10-23","start_date":"2026-10-23","end_date":"2026-10-24","description":"GLIMMER's first Dublin edition puts hypnotic tension, rolling techno and early-rave grit in the hands of Sémaé and Wotton, then gives queers, freaks and considerate allies a floor built for release rather than conformity.","link":"https://ra.co/events/2531028","ticket_url":"https://ra.co/events/2531028","location":"The Sound House, 28 Eden Quay, Dublin 1, Ireland","lat":53.35065,"lng":-6.25420,"vibe":"inclusive queer techno with hypnotic pressure and early-rave bite","intel":{"hours":"23:00–03:00 Friday 23 October into Saturday 24 October 2026.","entry_wait":"€15 tickets and an 18+ door are published; get there near opening rather than relying on late walk-up access.","best_arrival":"Arrive at 23:00 to catch the full duo bill and settle into the room before its four-hour peak.","crowd_mix":"Queers, freaks, music lovers and allies who understand the community-led floor are named by the organiser.","dress_code":"No mandatory style is published; intensity and self-expression are welcome without a fetish threshold.","host_inclusivity":"GLIMMER explicitly champions inclusion and frames the event as queer community space, not merely a friendly venue booking.","lineup":"Sémaé, Wotton.","age_limit":"18+.","source_urls":["https://ra.co/events/2531028"],"research_status":"ticketing_listing_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"Crystal Queer Club: Between Worlds","aliases":["Crystal Queer Club Between Worlds 2026","Tropical Samhain Between Worlds"],"city":"belfast","date":"2026-10-24","start_date":"2026-10-24","end_date":"2026-10-25","description":"Crystal Queer Club takes Samhain through Persephone's underworld: a Belfast Halloween rite of electronica, transformation and queer celebration that invites the crowd to dance through the dark rather than decorating it from a distance.","link":"https://ra.co/events/2543536","ticket_url":"https://ra.co/events/2543536","location":"The Pavilion Bar, 296–298 Ormeau Road, Belfast BT7 2GB, United Kingdom","lat":54.58953,"lng":-5.91673,"vibe":"Samhain queer electronica ritual with mythology, darkness and dance-floor celebration","intel":{"hours":"21:00–01:00 Saturday 24 October into Sunday 25 October 2026.","entry_wait":"£10 tickets and a 21+ door are listed; use the final ticket information to confirm entry conditions.","best_arrival":"Come around 21:00 to experience the ritual's opening atmosphere rather than arriving only for the closing hour.","crowd_mix":"Queer Belfast community, Halloween dancers and guests drawn to the event's mythic framing form the intended audience.","dress_code":"No compulsory costume is published, although dark, transformative Samhain styling naturally fits the concept.","host_inclusivity":"Crystal Queer Club names the event a queer celebration, with the room designed around collective transformation rather than mainstream Halloween spectacle.","lineup":"G!O ESCOBAR.","age_limit":"21+.","source_urls":["https://ra.co/events/2543536"],"research_status":"ticketing_listing_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"Dykes On Decks: Halloween 2026","aliases":["Dykes On Decks Halloween Brighton 2026"],"city":"brighton","date":"2026-10-30","start_date":"2026-10-30","end_date":"2026-10-31","description":"Dykes On Decks takes over both caves at The Tempest for a Halloween built on playful queer chaos: the upstairs holds the collective's own DJs while POPOLA drives Afro-LatinX and Caribbean heat below.","link":"https://ra.co/events/2536857","ticket_url":"https://ra.co/events/2536857","location":"The Tempest Inn, 159–161 Kings Road Arches, Brighton BN1 1NB, United Kingdom","lat":50.82167,"lng":-0.14520,"vibe":"two-room queer Halloween with techno, Latin bass and Afro-LatinX/Caribbean club energy","intel":{"hours":"22:00–03:00 Friday 30 October into Saturday 31 October 2026.","entry_wait":"Use the current RA ticket page and arrive before the costume-night rush; venue-wide takeovers can fill both rooms quickly.","best_arrival":"Reach doors at 22:00 to move between both rave caves before one room becomes your only practical choice.","crowd_mix":"Queer dancers, Dykes On Decks regulars and POPOLA's Afro-LatinX and Caribbean community meet in a deliberately mixed two-room format.","dress_code":"Fancy dress is encouraged but explicitly optional; wear something you can dance in across a multi-room night.","host_inclusivity":"Dykes On Decks platforms a range of artists and pairs its own queer party with POPOLA's cultural community space rather than flattening both audiences.","lineup":"Alex Berry, Charlotte Sometimes, India Shan, Lebby, Meg Ward, POPOLA residents.","age_limit":"18+.","source_urls":["https://ra.co/events/2536857"],"research_status":"ticketing_listing_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"JANUS VI: Rubber – Techno – Connection","aliases":["JANUS VI London 2026","JANUS Rubber Techno Connection"],"city":"london","date":"2026-11-06","start_date":"2026-11-06","end_date":"2026-11-07","description":"JANUS expands from intimate rubber ritual to The Cause's larger queer-fetish architecture: GAY RAGE and a hard techno bill soundtrack a room where gay, queer and trans men can take their rubber seriously and their desire without apology.","link":"https://ra.co/events/2472297","ticket_url":"https://ra.co/events/2472297","location":"The Cause, 60 Dock Road, London E16 1YZ, United Kingdom","lat":51.50891,"lng":0.01331,"vibe":"rubber-focused queer techno with immersive visuals and fetish-community intensity","intel":{"hours":"23:00–05:00 Friday 6 November into Saturday 7 November 2026.","entry_wait":"£20 standard tickets; members receive priority and discounts, but non-members can attend if they meet the rubber door expectations.","best_arrival":"Arrive close to 23:00, dressed for the event, to avoid testing the door at the post-midnight peak.","crowd_mix":"Gay, queer and trans men are the core community; respectful queer people and allies are welcome when they understand the culture.","dress_code":"Rubber is decisive. The organiser says guests arriving without it should not expect to pass the door.","host_inclusivity":"The event is community-specific rather than universal; its inclusivity depends on respecting a fetish culture, consent and the stated dress threshold.","lineup":"GAY RAGE, Command Control, Mickey RN, Rubberax.","age_limit":"18+.","source_urls":["https://ra.co/events/2472297","https://janus.gay/"],"research_status":"ticketing_listing_and_house_rules_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"POUFFE#2","aliases":["POUFFE 2 London","POUFFE London November 2026"],"city":"london","date":"2026-11-06","start_date":"2026-11-06","end_date":"2026-11-07","description":"POUFFE returns bigger, softer and faster: a high-tempo queer rave in Tottenham where acid, techno and hardcore-soft-porn maximalism share one anti-gatekeeping invitation to move hard and belong loudly.","link":"https://ra.co/events/2529325","ticket_url":"https://ra.co/events/2529325","location":"Unit 58, Millmead Industrial Estate, Mill Mead Road, London N17, United Kingdom","lat":51.59271,"lng":-0.06421,"vibe":"high-tempo queer acid and techno rave built on tenderness, maximalism and anti-gatekeeping","intel":{"hours":"22:00–05:00 Friday 6 November into Saturday 7 November 2026.","entry_wait":"£15 advance tickets are listed; the first edition sold out, so do not treat a late warehouse arrival as reliable.","best_arrival":"Come at 22:00 for a gentler entry and the full progression before the hard-clubbing peak.","crowd_mix":"Queer dancers and allies seeking an open, belonging-first high-tempo room are the intended crowd.","dress_code":"No mandatory outfit is published. The party celebrates bold looks but describes itself as proudly anti-gatekeeping.","host_inclusivity":"POUFFE explicitly centres openness, belonging and connection, pairing a high-intensity sound with a non-exclusionary door ethic.","lineup":"teleopath; further bill updates via organiser.","age_limit":"18+.","source_urls":["https://ra.co/events/2529325"],"research_status":"ticketing_listing_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"KINYXX London – Fetish Edition (Opening Party)","aliases":["KINYXX London Opening Party 2026","KINYXX London Fetish Edition"],"city":"london","date":"2026-11-13","start_date":"2026-11-13","end_date":"2026-11-14","description":"KINYXX lands in London with a mandatory fetish look, house-and-techno momentum and enough performance chaos to make Fire feel less like a venue booking than a temporary temple for chosen selves.","link":"https://ra.co/events/2512710","ticket_url":"https://ra.co/events/2512710","location":"Fire, 39 Parry Street, London SW8 1RT, United Kingdom","lat":51.48125,"lng":-0.12391,"vibe":"queer fetish house and techno with performances, dress ritual and body-positive excess","intel":{"hours":"23:00–05:00 Friday 13 November into Saturday 14 November 2026.","entry_wait":"Ticketing is live, but a ticket does not override the mandatory fetish dress code; arrive ready and carry valid ID.","best_arrival":"Use 23:00 doors to clear the costume check calmly and experience the opening-party production before its late peak.","crowd_mix":"Queer, fetish and open-minded dancers of varied genders, bodies and identities are invited into a performance-led room.","dress_code":"Mandatory: black, latex, harnesses, PVC, lingerie, mesh, rope, drag, cosplay, body paint and related fetish/fantasy looks are accepted.","host_inclusivity":"KINYXX publishes anti-phobia, permission-first and performer-boundary rules, plus an explicit statement that age, body, faith, race and gender are equal on the floor.","lineup":"To be announced by organiser.","age_limit":"18+.","source_urls":["https://ra.co/events/2512710"],"research_status":"ticketing_listing_and_house_rules_verified","updated_at":"2026-09-26T00:00:00Z"}}
]
$qa_uk_city_events$) e(name text,aliases jsonb,city text,date date,start_date date,end_date date,description text,link text,ticket_url text,location text,lat double precision,lng double precision,vibe text,intel jsonb)
), matches as (
 select s.*,x.id existing_id from src s left join lateral (select e.id from public.events e where lower(trim(e.city))=lower(trim(s.city)) and (lower(regexp_replace(trim(e.name),'[^a-z0-9]+','','gi'))=lower(regexp_replace(trim(s.name),'[^a-z0-9]+','','gi')) or exists(select 1 from jsonb_array_elements_text(s.aliases) a where lower(regexp_replace(trim(e.name),'[^a-z0-9]+','','gi'))=lower(regexp_replace(trim(a),'[^a-z0-9]+','','gi'))) or (e.start_date=s.start_date and lower(nullif(trim(e.link),'')) in(lower(s.link),lower(s.ticket_url)))) limit 1) x on true
), updates as (update public.events e set name=s.name,description=s.description,link=s.link,ticket_url=s.ticket_url,date=s.date,start_date=s.start_date,end_date=s.end_date,location=s.location,lat=s.lat,lng=s.lng,vibe=s.vibe,vibe_tags=array[]::text[],event_intel=s.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from matches s where e.id=s.existing_id returning e.id)
insert into public.events(name,city,description,link,ticket_url,date,start_date,end_date,location,lat,lng,vibe,vibe_tags,event_intel,seo_indexable,seo_quality_status,updated_at) select name,city,description,link,ticket_url,date,start_date,end_date,location,lat,lng,vibe,array[]::text[],intel,true,'approved',timezone('utc',now()) from matches where existing_id is null;

with src as (
 select * from jsonb_to_recordset($qa_uk_global_events$
[
{"name":"Bin Juice presents: Queer Rave with Marie Malarie and Josh Bell","aliases":["Bin Juice Queer Rave Newcastle 2026"],"date":"2026-10-10","start_date":"2026-10-10","end_date":"2026-10-11","description":"Bin Juice brings a little drag and a lot of dancing to Newcastle: Marie Malarie's London queer-underground sleaze meets Josh Bell's high-octane club logic across house, acid and pumping techno, with love and care stated as clearly as the no-camera rule.","link":"https://ra.co/events/2537851","ticket_url":"https://ra.co/events/2537851","location":"Cobalt Studios, 10–16 Boyd Street, Newcastle upon Tyne NE2 1AP, United Kingdom","vibe":"Newcastle queer rave with drag, acid, techno and a camera-free floor","intel":{"hours":"22:30–03:00 Saturday 10 October into Sunday 11 October 2026.","entry_wait":"£10–16 tickets; arrive early for the small independent venue rather than relying on peak-time entry.","best_arrival":"Doors at 22:30 give the fullest experience and a calmer way to navigate Cobalt Studios.","crowd_mix":"Queers, friends and allies are explicitly welcomed alongside Newcastle's acid, house and rave crowd.","dress_code":"No formal code is published; dance-ready and expressive works better than generic club polish.","host_inclusivity":"Cobalt publishes a no-camera policy and explicit bans on racism, sexism, homophobia and transphobia.","lineup":"Marie Malarie, Josh Bell.","age_limit":"18+.","source_urls":["https://ra.co/events/2537851"],"research_status":"ticketing_listing_verified_off_grid_city","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"Out & Wild Festival 2027","aliases":["Out and Wild 2027"],"date":"2027-07-23","start_date":"2027-07-23","end_date":"2027-07-26","description":"Out & Wild is four days designed around queer, questioning and curious women and non-binary people: a softer kind of festival infrastructure where wellness, connection and visibility matter as much as the party programme.","link":"https://www.visitbritain.com/en/things-to-do/lgbtqia-britain","ticket_url":"https://www.visitbritain.com/en/things-to-do/lgbtqia-britain","location":"United Kingdom — 2027 festival site to be confirmed by organiser","vibe":"queer women and non-binary wellness festival with connection at its core","intel":{"hours":"23–26 July 2027; detailed opening hours and site will be published by the organiser.","entry_wait":"Dates are confirmed, but do not book transport to an assumed site until the organiser releases the 2027 location and ticket conditions.","best_arrival":"Build travel around the final site and programme; this is a multi-day festival rather than a single nightlife door.","crowd_mix":"Queer, questioning and curious women and non-binary people are the festival's stated focus.","dress_code":"No formal look is indicated; outdoor comfort, weather layers and the final site guidance should lead.","host_inclusivity":"The festival is explicitly designed for communities underserved by standard LGBTQ+ event programming, with identity-specific rather than generic inclusion.","lineup":"2027 programme to be announced.","age_limit":"Confirm with organiser.","source_urls":["https://www.visitbritain.com/en/things-to-do/lgbtqia-britain"],"research_status":"official_destination_dates_verified_site_pending","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"Hand in Hand Festival 2027","aliases":["Hand in Hand Blackpool 2027"],"date":"2027-08-13","start_date":"2027-08-13","end_date":"2027-08-15","description":"Hand in Hand brings queer culture, friendship and solidarity to Blackpool for a weekend that treats LGBTQ+ public visibility as a shared act: seaside scale, community encounters and a programme built to make people feel less alone.","link":"https://handinhandfestival.org/about/","ticket_url":"https://handinhandfestival.org/about/","location":"Blackpool, England, United Kingdom — programme venues to be announced by organiser","vibe":"Blackpool queer culture festival rooted in visibility, friendship and solidarity","intel":{"hours":"13–15 August 2027; venue-by-venue timing remains to be announced.","entry_wait":"The festival dates and city are confirmed, but ticketing and individual venue logistics must wait for the organiser's programme release.","best_arrival":"Plan accommodation early for a summer Blackpool weekend, then build the final route from official venue information.","crowd_mix":"LGBTQ+ people, allies, community organisers, artists and visitors seeking public queer culture form the intended gathering.","dress_code":"No festival-wide rule is published; coastal weather layers and event-specific guidance will matter more than one look.","host_inclusivity":"The organiser explicitly frames the festival around queer culture, friendship, solidarity and making LGBTQ+ lives visible in public space.","lineup":"2027 programme to be announced.","age_limit":"Confirm programme-specific rules with organiser.","source_urls":["https://handinhandfestival.org/about/"],"research_status":"official_dates_and_city_verified_programme_pending","updated_at":"2026-09-26T00:00:00Z"}}
]
$qa_uk_global_events$) e(name text,aliases jsonb,date date,start_date date,end_date date,description text,link text,ticket_url text,location text,vibe text,intel jsonb)
), matches as (select s.*,x.id existing_id from src s left join lateral(select g.id from public.global_events g where lower(regexp_replace(trim(g.name),'[^a-z0-9]+','','gi'))=lower(regexp_replace(trim(s.name),'[^a-z0-9]+','','gi')) or exists(select 1 from jsonb_array_elements_text(s.aliases) a where lower(regexp_replace(trim(g.name),'[^a-z0-9]+','','gi'))=lower(regexp_replace(trim(a),'[^a-z0-9]+','','gi'))) or (g.start_date=s.start_date and lower(nullif(trim(g.link),'')) in(lower(s.link),lower(s.ticket_url))) limit 1)x on true), updates as(update public.global_events g set name=s.name,description=s.description,link=s.link,ticket_url=s.ticket_url,date=s.date,start_date=s.start_date,end_date=s.end_date,location=s.location,vibe=s.vibe,vibe_tags=array[]::text[],event_intel=s.intel,source='Queer Atlas editorial verification',last_checked='2026-09-26',event_status='scheduled' from matches s where g.id=s.existing_id returning g.id)
insert into public.global_events(name,date,start_date,end_date,location,vibe,vibe_tags,description,link,ticket_url,event_intel,source,last_checked,event_status) select name,date,start_date,end_date,location,vibe,array[]::text[],description,link,ticket_url,intel,'Queer Atlas editorial verification','2026-09-26','scheduled' from matches where existing_id is null;

do $qa_uk_event_guard$
begin
 if exists(select 1 from public.events where event_intel->>'updated_at'='2026-09-26T00:00:00Z' and (coalesce(trim(description),'')='' or coalesce(trim(location),'')='' or jsonb_array_length(coalesce(event_intel->'source_urls','[]'::jsonb))=0)) then raise exception 'UK city event missing required editorial data'; end if;
 if exists(select 1 from public.global_events where event_intel->>'updated_at'='2026-09-26T00:00:00Z' and (coalesce(trim(description),'')='' or coalesce(trim(location),'')='' or jsonb_array_length(coalesce(event_intel->'source_urls','[]'::jsonb))=0)) then raise exception 'UK global event missing required editorial data'; end if;
end;
$qa_uk_event_guard$;

commit;
